const { DateTime } = require('luxon');
const ZONE = 'Europe/Berlin';
const items = $input.all().map(i => i.json);
const leads = items.filter(x => x.rowType === 'lead');
const followUps = items.filter(x => x.rowType === 'followup');
const now = DateTime.now().setZone(ZONE);
const weekStart = now.minus({ days: 7 }).toISODate();
const recent = leads.filter(x => x.Date && String(x.Date) >= weekStart);
const norm = v => String(v || '').toLowerCase().trim();
const booked = recent.filter(x => norm(x.Outcome) === 'booked');
const callbacks = recent.filter(x => norm(x.Outcome) === 'callback requested');
const noBooking = recent.filter(x => norm(x.Outcome) === 'no booking');
const openFollowUps = followUps.filter(x => norm(x.Status) === 'open');
const lines = [];
lines.push('Weekly call digest for TourwithChe.');
lines.push('Week ending ' + now.toFormat('dd LLL yyyy') + ' (Berlin time).');
lines.push('');
lines.push('Calls this week: ' + recent.length);
lines.push('Bookings made: ' + booked.length);
lines.push('Callbacks requested: ' + callbacks.length);
lines.push('No booking: ' + noBooking.length);
lines.push('');
if (booked.length) {
  lines.push('Bookings:');
  booked.forEach(x => lines.push('- ' + x.Date + ' ' + (x.Time || '') + ' | ' + (x.Caller || 'unknown') + ' | ' + (x.Summary || '')));
  lines.push('');
}
if (openFollowUps.length) {
  lines.push('Open follow-ups:');
  openFollowUps.forEach(x => lines.push('- due ' + (x['Follow-up date'] || '?') + ' | ' + (x.Caller || 'unknown') + ' | ' + (x.Reason || '')));
  lines.push('');
} else {
  lines.push('No open follow-ups.');
  lines.push('');
}
const withSummary = recent.filter(x => x.Summary);
if (withSummary.length) {
  lines.push('Recent call summaries:');
  withSummary.slice(0, 5).forEach(x => lines.push('- ' + x.Date + ' | ' + (x.Caller || 'unknown') + ' | ' + x.Summary));
}
const body = lines.join('\n');
const subject = 'BrightMove weekly digest, week ending ' + now.toFormat('dd LLL yyyy');
return [{ json: { subject, body } }];
